#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` for the EPI app.

Run from the project root after:
    flutter create --org org.yfca --project-name epi_app --platforms android .

It sets minSdk 26, adds the permissions and receivers the app needs, disables
backup and device transfer of app data, sets the Arabic app name and copies the
native Kotlin sources from native/. It fails loudly if an anchor is missing.
"""
import glob
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
APP = os.path.join(ROOT, "android", "app")


def fail(msg):
    print("patch_android: " + msg, file=sys.stderr)
    sys.exit(1)


def patch_gradle():
    kts = os.path.join(APP, "build.gradle.kts")
    groovy = os.path.join(APP, "build.gradle")
    path = kts if os.path.exists(kts) else groovy
    if not os.path.exists(path):
        fail("app build.gradle(.kts) not found")
    src = open(path, encoding="utf-8").read()
    if path.endswith(".kts"):
        new, n = re.subn(r"minSdk\s*=\s*[^\n]+", "minSdk = 26", src)
    else:
        new, n = re.subn(r"minSdk(Version)?\s+[^\n]+", "minSdkVersion 26", src)
    if n == 0:
        fail("minSdk line not found in " + path)
    # Keep rules so release shrinking never strips SQLCipher or our receivers.
    open(os.path.join(APP, "proguard-rules.pro"), "w", encoding="utf-8").write(PROGUARD)
    if "proguard-rules.pro" not in new:
        if path.endswith(".kts"):
            new, k = re.subn(r"(release\s*\{)", r'\1\n            proguardFiles(getDefaultProguardFile("proguard-android.txt"), "proguard-rules.pro")', new, count=1)
        else:
            new, k = re.subn(r"(release\s*\{)", r"\1\n            proguardFiles getDefaultProguardFile('proguard-android.txt'), 'proguard-rules.pro'", new, count=1)
        if k == 0:
            fail("release build type not found in " + path)
    open(path, "w", encoding="utf-8").write(new)
    print("gradle: minSdk 26 and keep rules applied in " + os.path.basename(path))


PROGUARD = """# EPI app keep rules
-keep class net.zetetic.** { *; }
-keep class net.sqlcipher.** { *; }
-keep class com.davidmartos96.sqflite_sqlcipher.** { *; }
-keep class org.yfca.** { *; }
-dontwarn net.zetetic.**
-dontwarn net.sqlcipher.**
"""

PERMISSIONS = [
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.RECEIVE_BOOT_COMPLETED",
    "android.permission.READ_CALENDAR",
    "android.permission.WRITE_CALENDAR",
]

RECEIVERS = """
        <receiver android:name=".ReminderReceiver" android:exported="false" />
        <receiver android:name=".BootReceiver" android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED" />
                <action android:name="android.intent.action.TIME_SET" />
                <action android:name="android.intent.action.TIMEZONE_CHANGED" />
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />
            </intent-filter>
        </receiver>
"""

EXTRACTION_RULES = """<?xml version="1.0" encoding="utf-8"?>
<!-- No cloud backup and no device-to-device transfer of app data (FRS-SEC-06). -->
<data-extraction-rules>
    <cloud-backup>
        <exclude domain="root" />
        <exclude domain="file" />
        <exclude domain="database" />
        <exclude domain="sharedpref" />
        <exclude domain="external" />
    </cloud-backup>
    <device-transfer>
        <exclude domain="root" />
        <exclude domain="file" />
        <exclude domain="database" />
        <exclude domain="sharedpref" />
        <exclude domain="external" />
    </device-transfer>
</data-extraction-rules>
"""


def patch_manifest():
    path = os.path.join(APP, "src", "main", "AndroidManifest.xml")
    if not os.path.exists(path):
        fail("AndroidManifest.xml not found")
    src = open(path, encoding="utf-8").read()

    perms = "".join(
        '    <uses-permission android:name="%s" />\n' % p for p in PERMISSIONS if p not in src
    )
    if "<application" not in src:
        fail("<application> not found in manifest")
    src = src.replace("<application", perms + "    <application", 1)

    def app_attrs(m):
        tag = m.group(0)
        tag = re.sub(r'android:label="[^"]*"', 'android:label="التحصين الموسع"', tag)
        for attr, value in (
            ("android:allowBackup", "false"),
            ("android:dataExtractionRules", "@xml/data_extraction_rules"),
        ):
            if attr not in tag:
                tag = tag.replace("<application", '<application\n        %s="%s"' % (attr, value), 1)
        return tag

    src, n = re.subn(r"<application[^>]*>", app_attrs, src, count=1)
    if n == 0:
        fail("could not patch <application> attributes")

    if "ReminderReceiver" not in src:
        if "</application>" not in src:
            fail("</application> not found")
        src = src.replace("</application>", RECEIVERS + "    </application>", 1)

    open(path, "w", encoding="utf-8").write(src)
    xml_dir = os.path.join(APP, "src", "main", "res", "xml")
    os.makedirs(xml_dir, exist_ok=True)
    open(os.path.join(xml_dir, "data_extraction_rules.xml"), "w", encoding="utf-8").write(EXTRACTION_RULES)
    print("manifest: permissions, receivers, backup rules and label applied")


def copy_native():
    found = glob.glob(os.path.join(APP, "src", "main", "kotlin", "**", "MainActivity.kt"), recursive=True)
    if not found:
        fail("generated MainActivity.kt not found")
    target_dir = os.path.dirname(found[0])
    generated = open(found[0], encoding="utf-8").read()
    m = re.search(r"^package\s+([\w.]+)", generated, re.M)
    if not m:
        fail("package line not found in generated MainActivity.kt")
    package = m.group(1)
    for f in glob.glob(os.path.join(ROOT, "native", "*.kt")):
        src = open(f, encoding="utf-8").read()
        src = re.sub(r"^package\s+[\w.]+", "package " + package, src, count=1, flags=re.M)
        open(os.path.join(target_dir, os.path.basename(f)), "w", encoding="utf-8").write(src)
    print("native: Kotlin sources copied into package " + package)


def check_fonts():
    for name in ("Amiri-Regular.ttf", "Amiri-Bold.ttf"):
        p = os.path.join(ROOT, "assets", "fonts", name)
        if not os.path.exists(p) or os.path.getsize(p) < 10000:
            fail("missing font assets/fonts/%s (run tool/get_fonts.sh)" % name)
    print("fonts: present")


if __name__ == "__main__":
    patch_gradle()
    patch_manifest()
    copy_native()
    check_fonts()
    shutil.rmtree(os.path.join(ROOT, "build"), ignore_errors=True)
    print("patch_android: done")
